#include <bits/stdc++.h>
using namespace std; struct P{long double x,y;};P operator-(P a,P b){return{a.x-b.x,a.y-b.y};}long double cross(P a,P b){return a.x*b.y-a.y*b.x;}long double dot(P a,P b){return a.x*b.x+a.y*b.y;}long double norm(P a){return sqrtl(dot(a,a));}int sgn(long double x){return (x>0)-(x<0);}bool on(P a,P b,P p){return sgn(cross(b-a,p-a))==0&&dot(p-a,p-b)<=0;}bool hit(P a,P b,P c,P d){long double c1=cross(b-a,c-a),c2=cross(b-a,d-a),c3=cross(d-c,a-c),c4=cross(d-c,b-c);if(sgn(c1)*sgn(c2)<0&&sgn(c3)*sgn(c4)<0)return true;return on(a,b,c)||on(a,b,d)||on(c,d,a)||on(c,d,b);}long double pd(P a,P b,P p){P v=b-a,w=p-a;if(dot(v,v)==0)return norm(w);long double t=max((long double)0,min((long double)1,dot(w,v)/dot(v,v)));return norm(P{p.x-a.x-v.x*t,p.y-a.y-v.y*t});}int main(){ios::sync_with_stdio(false);cin.tie(nullptr);int T;cin>>T;cout<<fixed<<setprecision(12);while(T--){P a,b,c,d;cin>>a.x>>a.y>>b.x>>b.y>>c.x>>c.y>>d.x>>d.y;if(hit(a,b,c,d))cout<<0.0L<<'\n';else cout<<min({pd(a,b,c),pd(a,b,d),pd(c,d,a),pd(c,d,b)})<<'\n';}}
